function solve(region, consent) {
  // EU policy: telemetry defaults to disabled unless consent is explicitly true
  if (region === 'EU') {
    return consent === true;
  }

  // US policy: telemetry defaults to enabled unless consent is explicitly false
  if (region === 'US') {
    return consent !== false;
  }

  // Default case: assume US behavior if region is unknown
  return true;
}
